const eventLog=window.NNPavingEvents=window.NNPavingEvents||[];
const track=(name,detail={})=>{eventLog.push({name,...detail,at:new Date().toISOString()});};
document.addEventListener('click',e=>{const target=e.target.closest?.('a,button');if(!target)return;const href=target.getAttribute('href')||'';if(href.startsWith('tel:'))track('phone_click');else if(href.startsWith('mailto:'))track('email_open');else if(href.includes('facebook.com'))track('facebook_click');else if(href==='/contact/'&&!eventLog.some(x=>x.name==='quote_start'))track('quote_start');else if(target.matches('[data-photo]'))track('gallery_open');});
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('.nav'),header=document.querySelector('header');
const setMenu=(open,focusLink=false)=>{if(!menu||!nav)return;menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close site menu':'Open site menu');nav.classList.toggle('open',open);if(open&&focusLink)nav.querySelector('a')?.focus();};
menu?.addEventListener('click',()=>setMenu(menu.getAttribute('aria-expanded')!=='true',true));
nav?.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>setMenu(false)));
document.addEventListener('click',e=>{if(nav?.classList.contains('open')&&!header?.contains(e.target))setMenu(false);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('open')){setMenu(false);menu?.focus();}});
window.addEventListener('resize',()=>{if(window.innerWidth>760&&nav?.classList.contains('open'))setMenu(false);});
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));let count=0;document.querySelectorAll('[data-category]').forEach(x=>{x.hidden=b.dataset.filter!=='all'&&x.dataset.category!==b.dataset.filter;if(!x.hidden)count++;});const countLabel=document.querySelector('#gallery-count');if(countLabel)countLabel.textContent=count+' photograph'+(count===1?'':'s');}));
const dialog=document.querySelector('.lightbox');let photoTrigger;
document.querySelectorAll('[data-photo]').forEach(b=>b.addEventListener('click',()=>{photoTrigger=b;document.querySelector('#large-photo').src=b.dataset.photo;document.querySelector('#large-photo').alt=b.querySelector('img').alt;document.querySelector('#large-caption').textContent=b.dataset.caption;dialog.showModal();dialog.querySelector('[data-close]')?.focus();}));
document.querySelector('[data-close]')?.addEventListener('click',()=>dialog.close());dialog?.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});dialog?.addEventListener('close',()=>photoTrigger?.focus());
const form=document.querySelector('#quote-form');
let quoteStarted=false;form?.addEventListener('focusin',()=>{if(!quoteStarted&&!eventLog.some(x=>x.name==='quote_start')){quoteStarted=true;track('quote_start');}});
form?.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const f=new FormData(form);const postcode=String(f.get('postcode')).trim().toUpperCase();const post=form.elements.postcode;post.setCustomValidity('');if(!/^[A-Z]{1,2}\d[A-Z\d]?\s*\d[A-Z]{2}$/i.test(postcode)){post.setCustomValidity('Please enter a full UK postcode, such as NN1 1AA.');post.reportValidity();return;}track('quote_review',{service:String(f.get('service')||'')});const message=`Hello Leon,\n\nI would like a free quotation for ${f.get('service')}.\n\nProject priority: ${f.get('goal')}\nPractical notes: ${f.get('site_notes')}\n\nName: ${String(f.get('name')).trim()}\nProperty postcode: ${postcode}\nEmail: ${f.get('email')}\nPhone: ${f.get('phone')||'Not provided'}\n\nProject details:\n${String(f.get('details')).trim()}\n\nPlease let me know the next steps. Thank you.`;document.querySelector('#quote-message').value=message;document.querySelector('#email-enquiry').href='mailto:NNPaving@gmail.com?subject='+encodeURIComponent('Free quote enquiry — '+postcode)+'&body='+encodeURIComponent(message);const r=document.querySelector('#quote-result');r.hidden=false;document.querySelector('#quote-status').textContent='Not sent yet. Open your email app, add any photographs and send to NNPaving@gmail.com.';r.focus();r.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});});
form?.elements.postcode.addEventListener('input',()=>form.elements.postcode.setCustomValidity(''));
form?.addEventListener('input',()=>{document.querySelector('#quote-result').hidden=true;});
document.querySelector('#copy-enquiry')?.addEventListener('click',async()=>{const t=document.querySelector('#quote-message');try{await navigator.clipboard.writeText(t.value);document.querySelector('#quote-status').textContent='Copied. Paste into an email addressed to NNPaving@gmail.com. Your enquiry has not been sent.';}catch{t.focus();t.select();document.querySelector('#quote-status').textContent='Select and copy the message above, then paste it into your email service.'}});
